<?php
require_once __DIR__.'/includes/config.php'; require_admin();
$msg='';$error='';
try {
 if($_SERVER['REQUEST_METHOD']==='POST'){
  verify_csrf(); $action=$_POST['action']??'lesson';
  if($action==='lesson'){
   $class=(int)($_POST['class_id']??0);$subject=(int)($_POST['subject_id']??0);$teacher=(int)($_POST['teacher_id']??0);$room=trim($_POST['room']??'');$day=(int)($_POST['day_of_week']??0);$start=$_POST['start_time']??'';$end=$_POST['end_time']??'';$year=trim($_POST['academic_year']??date('Y'));$term=trim($_POST['term']??'Term 1');
   if(!$class||!$subject||!$teacher||$room===''||$day<1||$day>6||!preg_match('/^\d{2}:\d{2}$/',$start)||!preg_match('/^\d{2}:\d{2}$/',$end)||$end<=$start) throw new RuntimeException('Complete all fields and use a valid time range.');
   $q=$dbh->prepare("SELECT id FROM srms_timetable WHERE active=1 AND day_of_week=:d AND start_time < :endtime AND end_time > :starttime AND (teacher_id=:teacher OR room=:room OR class_id=:class) LIMIT 1");$q->execute([':d'=>$day,':endtime'=>$end,':starttime'=>$start,':teacher'=>$teacher,':room'=>$room,':class'=>$class]);if($q->fetch()) throw new RuntimeException('Clash detected: the teacher, room, or class already has a lesson during this time.');
   $q=$dbh->prepare('INSERT INTO srms_timetable(class_id,subject_id,teacher_id,room,day_of_week,start_time,end_time,academic_year,term,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$class,$subject,$teacher,$room,$day,$start,$end,$year,$term,$_SESSION['admin_id']??null]);audit_log($dbh,'TIMETABLE_CREATE','Added timetable lesson');$msg='Lesson added. No teacher, room, or class clash detected.';
  } elseif($action==='exam'){
   $title=trim($_POST['title']??'');$class=(int)($_POST['class_id']??0);$subject=(int)($_POST['subject_id']??0);$teacher=(int)($_POST['teacher_id']??0);$room=trim($_POST['room']??'');$date=$_POST['exam_date']??'';$start=$_POST['start_time']??'';$end=$_POST['end_time']??'';$year=trim($_POST['academic_year']??date('Y'));$term=trim($_POST['term']??'Term 1');
   if(!$title||!$class||!$subject||!$teacher||!$room||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!preg_match('/^\d{2}:\d{2}$/',$start)||!preg_match('/^\d{2}:\d{2}$/',$end)||$end<=$start) throw new RuntimeException('Complete all examination fields correctly.');
   $q=$dbh->prepare("SELECT id FROM srms_examinations WHERE status<>'cancelled' AND exam_date=:d AND start_time < :endtime AND end_time > :starttime AND (teacher_id=:teacher OR room=:room OR class_id=:class) LIMIT 1");$q->execute([':d'=>$date,':endtime'=>$end,':starttime'=>$start,':teacher'=>$teacher,':room'=>$room,':class'=>$class]);if($q->fetch())throw new RuntimeException('Examination clash detected for teacher, room, or class.');
   $q=$dbh->prepare("INSERT INTO srms_examinations(title,class_id,subject_id,teacher_id,room,exam_date,start_time,end_time,academic_year,term) VALUES(?,?,?,?,?,?,?,?,?,?)");$q->execute([$title,$class,$subject,$teacher,$room,$date,$start,$end,$year,$term]);audit_log($dbh,'EXAM_SCHEDULE_CREATE','Created examination schedule');$msg='Examination scheduled as draft.';
  } elseif($action==='publish') { $id=(int)($_POST['exam_id']??0);$q=$dbh->prepare("UPDATE srms_examinations SET status='published' WHERE id=? AND status='draft'");$q->execute([$id]);$msg=$q->rowCount()?'Examination timetable published.':'No draft examination was changed.';audit_log($dbh,'EXAM_SCHEDULE_PUBLISH','Published examination '.$id); }
 }
 $classes=$dbh->query('SELECT id,ClassName,Section FROM tblclasses ORDER BY ClassNameNumeric,Section')->fetchAll();$subjects=$dbh->query('SELECT id,SubjectName FROM tblsubjects ORDER BY SubjectName')->fetchAll();$teachers=$dbh->query('SELECT id,full_name FROM teachers WHERE status=1 ORDER BY full_name')->fetchAll();
 $lessons=$dbh->query('SELECT t.*,c.ClassName,c.Section,s.SubjectName,te.full_name FROM srms_timetable t JOIN tblclasses c ON c.id=t.class_id JOIN tblsubjects s ON s.id=t.subject_id JOIN teachers te ON te.id=t.teacher_id WHERE t.active=1 ORDER BY t.day_of_week,t.start_time')->fetchAll();
 $exams=$dbh->query("SELECT x.*,c.ClassName,c.Section,s.SubjectName,te.full_name FROM srms_examinations x JOIN tblclasses c ON c.id=x.class_id JOIN tblsubjects s ON s.id=x.subject_id LEFT JOIN teachers te ON te.id=x.teacher_id WHERE x.status<>'cancelled' ORDER BY x.exam_date,x.start_time")->fetchAll();
} catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Unable to complete operation. Confirm the Phase 12 migration is installed.';if(!($e instanceof RuntimeException))error_log('SRMS timetable: '.$e->getMessage());$classes=$classes??[];$subjects=$subjects??[];$teachers=$teachers??[];$lessons=$lessons??[];$exams=$exams??[];}
$days=[1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday'];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Timetable & Exams | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"><style>@media print{.no-print,form,.navbar,.left-sidebar{display:none!important}.panel{border:0!important}.container-fluid{width:100%}}.srms-page{padding:18px}.table-responsive{overflow-x:auto}</style></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container-fluid srms-page"><div class="no-print" style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px"><h2>Timetable & Examination Scheduling</h2><div><a class="btn btn-default" href="dashboard.php">Dashboard</a> <button class="btn btn-primary" onclick="window.print()">Export / Print PDF</button></div></div><?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="row no-print"><div class="col-md-6"><div class="panel"><div class="panel-heading"><h3>Add weekly lesson</h3></div><div class="panel-body"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="lesson"><div class="form-group"><label>Class</label><select class="form-control" name="class_id" required><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['ClassName'].' '.$c['Section'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Subject</label><select class="form-control" name="subject_id" required><?php foreach($subjects as $v):?><option value="<?=$v['id']?>"><?=e($v['SubjectName'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Teacher</label><select class="form-control" name="teacher_id" required><?php foreach($teachers as $v):?><option value="<?=$v['id']?>"><?=e($v['full_name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Room</label><input class="form-control" name="room" maxlength="80" required></div><div class="form-group"><label>Day</label><select class="form-control" name="day_of_week"><?php foreach($days as $k=>$v):?><option value="<?=$k?>"><?=e($v)?></option><?php endforeach;?></select></div><div class="row"><div class="col-xs-6"><label>Start</label><input type="time" class="form-control" name="start_time" required></div><div class="col-xs-6"><label>End</label><input type="time" class="form-control" name="end_time" required></div></div><div class="row"><div class="col-xs-6"><label>Academic year</label><input class="form-control" name="academic_year" value="<?=date('Y')?>" required></div><div class="col-xs-6"><label>Term</label><select class="form-control" name="term"><option>Term 1</option><option>Term 2</option><option>Term 3</option></select></div></div><br><button class="btn btn-success">Add lesson</button></form></div></div></div><div class="col-md-6"><div class="panel"><div class="panel-heading"><h3>Schedule examination</h3></div><div class="panel-body"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="exam"><div class="form-group"><label>Examination title</label><input class="form-control" name="title" required maxlength="180"></div><div class="form-group"><label>Class</label><select class="form-control" name="class_id"><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['ClassName'].' '.$c['Section'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Subject</label><select class="form-control" name="subject_id"><?php foreach($subjects as $v):?><option value="<?=$v['id']?>"><?=e($v['SubjectName'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Invigilator / teacher</label><select class="form-control" name="teacher_id"><?php foreach($teachers as $v):?><option value="<?=$v['id']?>"><?=e($v['full_name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Room</label><input class="form-control" name="room" required></div><div class="form-group"><label>Date</label><input type="date" class="form-control" name="exam_date" required></div><div class="row"><div class="col-xs-6"><label>Start</label><input type="time" class="form-control" name="start_time" required></div><div class="col-xs-6"><label>End</label><input type="time" class="form-control" name="end_time" required></div></div><div class="row"><div class="col-xs-6"><label>Academic year</label><input class="form-control" name="academic_year" value="<?=date('Y')?>" required></div><div class="col-xs-6"><label>Term</label><select class="form-control" name="term"><option>Term 1</option><option>Term 2</option><option>Term 3</option></select></div></div><br><button class="btn btn-success">Save examination draft</button></form></div></div></div></div><div class="panel"><div class="panel-heading"><h3>Weekly timetable</h3></div><div class="panel-body table-responsive"><table class="table table-striped"><thead><tr><th>Day</th><th>Time</th><th>Class</th><th>Subject</th><th>Teacher</th><th>Room</th><th>Year / Term</th></tr></thead><tbody><?php foreach($lessons as $l):?><tr><td><?=e($days[$l['day_of_week']]??'')?></td><td><?=e(substr($l['start_time'],0,5).'–'.substr($l['end_time'],0,5))?></td><td><?=e($l['ClassName'].' '.$l['Section'])?></td><td><?=e($l['SubjectName'])?></td><td><?=e($l['full_name'])?></td><td><?=e($l['room'])?></td><td><?=e($l['academic_year'].' / '.$l['term'])?></td></tr><?php endforeach;?><?php if(!$lessons):?><tr><td colspan="7">No lessons scheduled.</td></tr><?php endif;?></tbody></table></div></div><div class="panel"><div class="panel-heading"><h3>Examination timetable</h3><p>Published examinations are marked for sharing with students and parents.</p></div><div class="panel-body table-responsive"><table class="table table-striped"><thead><tr><th>Date</th><th>Time</th><th>Exam</th><th>Class</th><th>Subject</th><th>Room</th><th>Status</th><th class="no-print">Action</th></tr></thead><tbody><?php foreach($exams as $x):?><tr><td><?=e($x['exam_date'])?></td><td><?=e(substr($x['start_time'],0,5).'–'.substr($x['end_time'],0,5))?></td><td><?=e($x['title'])?></td><td><?=e($x['ClassName'].' '.$x['Section'])?></td><td><?=e($x['SubjectName'])?></td><td><?=e($x['room'])?></td><td><?=e(ucfirst($x['status']))?></td><td class="no-print"><?php if($x['status']==='draft'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="publish"><input type="hidden" name="exam_id" value="<?=$x['id']?>"><button class="btn btn-xs btn-primary">Publish</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$exams):?><tr><td colspan="8">No examinations scheduled.</td></tr><?php endif;?></tbody></table></div></div></div></body></html>
